package com.portfolio.assetory.payment.service;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.portfolio.assetory.access.domain.ProductAccess;import com.portfolio.assetory.access.repository.ProductAccessRepository;import com.portfolio.assetory.global.exception.*;import com.portfolio.assetory.order.domain.*;import com.portfolio.assetory.order.repository.*;import com.portfolio.assetory.payment.domain.Payment;import com.portfolio.assetory.payment.dto.request.MockPaymentRequest;import com.portfolio.assetory.payment.dto.response.MockPaymentResponse;import com.portfolio.assetory.payment.repository.PaymentRepository;
@Service @Transactional(readOnly=true) public class PaymentService {private final OrderRepository orders;private final OrderItemRepository items;private final PaymentRepository payments;private final ProductAccessRepository access;private final com.portfolio.assetory.cart.repository.CartItemRepository cartItems;public PaymentService(OrderRepository orders,OrderItemRepository items,PaymentRepository payments,ProductAccessRepository access,com.portfolio.assetory.cart.repository.CartItemRepository cartItems){this.orders=orders;this.items=items;this.payments=payments;this.access=access;this.cartItems=cartItems;}@Transactional public MockPaymentResponse execute(Long userId,MockPaymentRequest request){Order order=orders.findWithBuyerById(request.orderId()).orElseThrow(()->new BusinessException(ErrorCode.ORDER_NOT_FOUND));if(!order.getBuyer().getId().equals(userId))throw new BusinessException(ErrorCode.FORBIDDEN);if(order.getStatus()!=OrderStatus.PENDING_PAYMENT||payments.existsByOrderId(order.getId()))throw new BusinessException(ErrorCode.ORDER_NOT_PAYABLE);boolean success=request.result()==MockPaymentRequest.Result.SUCCESS;Payment payment=payments.save(Payment.complete(order,success));if(success){order.markPaid();java.util.List<OrderItem> orderItems=items.findWithProductByOrderId(order.getId());for(OrderItem item:orderItems)access.save(ProductAccess.grant(order.getBuyer(),item));cartItems.deleteByUserIdAndProductIdIn(userId,orderItems.stream().map(item->item.getProduct().getId()).toList());}else order.markPaymentFailed();return MockPaymentResponse.from(payment);}public com.portfolio.assetory.payment.dto.response.PaymentResponse get(Long userId,Long paymentId){Payment payment=payments.findByIdAndOrderBuyerId(paymentId,userId).orElseThrow(()->new BusinessException(ErrorCode.PAYMENT_NOT_FOUND));return com.portfolio.assetory.payment.dto.response.PaymentResponse.from(payment);}}
